<template>
  <div :class="embedded ? 'directory' : 'directory flex min-h-screen'"><OwnerSidebar v-if="!embedded" /><main class="content" :class="{ 'flex-1': !embedded }">
    <header><div><small>PROCUREMENT</small><h1>Supplier Directory</h1><p>Clinic-managed business contacts. Suppliers do not sign in or receive orders in AesthetiCare.</p></div><button v-if="canCreate" @click="openCreate">Add supplier</button></header>
    <p v-if="error" class="error">{{ error }}</p><p v-if="notice" class="success">{{ notice }}</p><section class="summary"><article><b>{{ associations.length }}</b>My clinic suppliers</article><article><b>{{ activeCount }}</b>Active for procurement</article><article><b>{{ reviewCount }}</b>FDA checks to review</article></section>
    <section class="toolbar"><input v-model="search" placeholder="Search business, contact, or category" /><select v-model="status"><option value="">All statuses</option><option>Active</option><option>Inactive</option><option>For review</option></select><label><input v-model="showDirectory" type="checkbox" @change="loadDirectory" /> Include shared directory</label></section>
    <p v-if="loading">Loading supplier directory…</p><section v-else-if="visible.length" class="grid"><article v-for="s in visible" :key="s.key" class="card"><div class="top"><div><h2>{{ s.businessName }}</h2><p>{{ s.category || 'Uncategorized supplier' }}</p></div><b>{{ s.associationStatus }}</b></div><dl><div><dt>Contact</dt><dd>{{ s.contactPerson || '—' }}</dd></div><div><dt>Email</dt><dd>{{ s.email || '—' }}</dd></div><div><dt>Phone</dt><dd>{{ s.contactNumber || '—' }}</dd></div><div><dt>FDA LTO</dt><dd>{{ s.regulatory?.ltoNumber || 'Not recorded' }}</dd></div><div><dt>Check</dt><dd>{{ label(s.regulatory?.verificationStatus) }}</dd></div></dl><p v-if="s.notes">Internal note: {{ s.notes }}</p><div class="actions"><button v-if="s.directoryOnly && canCreate" @click="associate(s)">Add to my clinic</button><button v-else-if="canManage" @click="edit(s)">Edit relationship</button><a href="https://verification.fda.gov.ph/" target="_blank" rel="noopener noreferrer">Verify on FDA ↗</a></div></article></section><section v-else class="empty"><h2>No supplier contacts found</h2><p>Add a clinic contact, or include the shared directory.</p></section>
    <div v-if="showForm" class="overlay"><form class="modal" @submit.prevent="save"><header><h2>{{ editing ? 'Update clinic supplier' : 'Add supplier' }}</h2><button type="button" @click="close">×</button></header><p v-if="!editing">Creates a business contact and associates it only with this clinic. Mark it shared only when suitable for reuse; clinic notes are never shared.</p><div class="form"><label>Business name *<input v-model.trim="form.businessName" required /></label><label>Category<input v-model.trim="form.category" /></label><label>Contact person<input v-model.trim="form.contactPerson" /></label><label>Email<input v-model.trim="form.email" type="email" /></label><label>Contact number<input v-model.trim="form.contactNumber" /></label><label>Address<input v-model.trim="form.address" /></label><label>Relationship status<select v-model="form.associationStatus"><option>Active</option><option>Inactive</option><option>For review</option></select></label><label>FDA LTO number<input v-model.trim="form.ltoNumber" /></label><label>Establishment category<input v-model.trim="form.establishmentCategory" /></label><label>FDA check status<select v-model="form.verificationStatus"><option value="not_checked">Not checked</option><option value="checked_valid">Checked valid</option><option value="expired_invalid">Expired / invalid</option><option value="not_applicable">Not applicable</option><option value="for_review">For review</option></select></label><label>Checked date<input v-model="form.checkedAt" type="date" /></label><label class="wide">Internal clinic notes<textarea v-model.trim="form.notes" /></label><label v-if="!editing" class="wide"><input v-model="form.sharedDirectory" type="checkbox" /> Reusable shared-directory contact</label></div><footer><button type="button" @click="close">Cancel</button><button :disabled="saving">{{ saving ? 'Saving…' : 'Save supplier' }}</button></footer></form></div>
  </main></div>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import { collection, doc, getDoc, getDocs, query, serverTimestamp, setDoc, updateDoc, where } from 'firebase/firestore'
import { onAuthStateChanged } from 'firebase/auth'
import OwnerSidebar from '@/components/sidebar/OwnerSidebar.vue'
import { auth, db } from '@/config/firebaseConfig'
import { loadOwnerBranchScope } from '@/utils/ownerBranchScope'
import { usePermissions } from '@/composables/usePermissions'
defineProps({ embedded: { type: Boolean, default: false } })
const { hasPermission, isClinicAdminOwner } = usePermissions()
const loading=ref(true),saving=ref(false),error=ref(''),notice=ref(''),search=ref(''),status=ref(''),showDirectory=ref(false),showForm=ref(false),editing=ref(null),associations=ref([]),directory=ref([]),scope=ref({branchId:'',ownerId:''})
const blank=()=>({businessName:'',category:'',contactPerson:'',email:'',contactNumber:'',address:'',associationStatus:'Active',notes:'',ltoNumber:'',establishmentCategory:'',verificationStatus:'not_checked',checkedAt:'',sharedDirectory:false}); const form=ref(blank())
const canCreate=computed(()=>isClinicAdminOwner.value||hasPermission('suppliers:create')),canManage=computed(()=>isClinicAdminOwner.value||hasPermission('suppliers:update')),activeCount=computed(()=>associations.value.filter(x=>x.associationStatus==='Active').length),reviewCount=computed(()=>associations.value.filter(x=>['for_review','expired_invalid'].includes(x.regulatory?.verificationStatus)).length)
const visible=computed(()=>{const seen=new Set();return [...associations.value,...(showDirectory.value?directory.value:[])].filter(s=>{const id=s.supplierId||s.id;if(seen.has(id))return false;seen.add(id);return(!search.value||[s.businessName,s.contactPerson,s.email,s.category].join(' ').toLowerCase().includes(search.value.toLowerCase()))&&(!status.value||s.associationStatus===status.value)})})
const label=v=>({not_checked:'Not checked',checked_valid:'Checked valid',expired_invalid:'Expired / invalid',not_applicable:'Not applicable',for_review:'For review'}[v]||'Not checked')
const view=(supplier,link={})=>({...supplier,supplierId:supplier.id,key:link.id||supplier.id,associationId:link.id||'',associationStatus:link.status||'Active',notes:link.internalNotes||'',regulatory:supplier.regulatory||{},directoryOnly:!link.id,canEditBusiness:supplier.createdForClinicId===scope.value.ownerId})
async function load(){if(!scope.value.branchId)return;loading.value=true;try{const links=await getDocs(query(collection(db,'clinicSuppliers'),where('branchId','==',scope.value.branchId)));associations.value=(await Promise.all(links.docs.map(async l=>{const s=await getDoc(doc(db,'suppliers',l.data().supplierId));return s.exists()?view({id:s.id,...s.data()},{id:l.id,...l.data()}):null}))).filter(Boolean);if(showDirectory.value)await loadDirectory()}catch(e){error.value=e.message||'Unable to load supplier contacts.'}finally{loading.value=false}}
async function loadDirectory(){try{const rows=await getDocs(query(collection(db,'suppliers'),where('sharedDirectory','==',true)));directory.value=rows.docs.map(s=>view({id:s.id,...s.data()}))}catch(e){error.value=e.message||'Unable to load the shared directory.'}}
async function associate(s){if(!canCreate.value)return;await setDoc(doc(collection(db,'clinicSuppliers')),{clinicId:scope.value.ownerId,branchId:scope.value.branchId,supplierId:s.supplierId,status:'Active',internalNotes:'',associatedAt:serverTimestamp(),createdBy:auth.currentUser.uid,updatedBy:auth.currentUser.uid,updatedAt:serverTimestamp()});notice.value='Supplier added to this clinic.';await load()}
function openCreate(){editing.value=null;form.value=blank();showForm.value=true}function edit(s){editing.value=s;form.value={...blank(),businessName:s.businessName,category:s.category,contactPerson:s.contactPerson,email:s.email,contactNumber:s.contactNumber,address:s.address,associationStatus:s.associationStatus,notes:s.notes,ltoNumber:s.regulatory.ltoNumber||'',establishmentCategory:s.regulatory.establishmentCategory||'',verificationStatus:s.regulatory.verificationStatus||'not_checked',checkedAt:s.regulatory.checkedAt||''};showForm.value=true}function close(){showForm.value=false;editing.value=null}
async function save(){if(!scope.value.branchId)return;saving.value=true;try{const regulatory={ltoNumber:form.value.ltoNumber,establishmentCategory:form.value.establishmentCategory,verificationStatus:form.value.verificationStatus,checkedAt:form.value.checkedAt||null,checkedBy:auth.currentUser.uid,verificationSource:'https://verification.fda.gov.ph/'};if(editing.value){if(editing.value.canEditBusiness)await updateDoc(doc(db,'suppliers',editing.value.supplierId),{businessName:form.value.businessName,category:form.value.category,contactPerson:form.value.contactPerson,email:form.value.email,contactNumber:form.value.contactNumber,address:form.value.address,regulatory,updatedAt:serverTimestamp(),updatedBy:auth.currentUser.uid});await updateDoc(doc(db,'clinicSuppliers',editing.value.associationId),{status:form.value.associationStatus,internalNotes:form.value.notes,updatedAt:serverTimestamp(),updatedBy:auth.currentUser.uid})}else{const normal=v=>String(v||'').replace(/[^a-z0-9]/gi,'').toLowerCase(), duplicate=associations.value.find(s=>normal(s.businessName)===normal(form.value.businessName)&&(normal(s.email)===normal(form.value.email)||normal(s.contactNumber)===normal(form.value.contactNumber)));if(duplicate)throw Error(`A matching supplier contact (${duplicate.businessName}) is already associated with this clinic.`);const r=doc(collection(db,'suppliers'));await setDoc(r,{businessName:form.value.businessName,category:form.value.category,contactPerson:form.value.contactPerson,email:form.value.email,contactNumber:form.value.contactNumber,address:form.value.address,sharedDirectory:form.value.sharedDirectory,createdForClinicId:scope.value.ownerId,regulatory,status:'Active',createdAt:serverTimestamp(),createdBy:auth.currentUser.uid,updatedAt:serverTimestamp()});await setDoc(doc(collection(db,'clinicSuppliers')),{clinicId:scope.value.ownerId,branchId:scope.value.branchId,supplierId:r.id,status:form.value.associationStatus,internalNotes:form.value.notes,associatedAt:serverTimestamp(),createdBy:auth.currentUser.uid,updatedBy:auth.currentUser.uid,updatedAt:serverTimestamp()})}notice.value='Supplier contact saved.';close();await load()}catch(e){error.value=e.message||'Unable to save supplier.'}finally{saving.value=false}}
onMounted(()=>onAuthStateChanged(auth,async u=>{if(u){scope.value=await loadOwnerBranchScope(db,u.uid);await load()}}))
</script>
<style scoped>
.directory{background:#fcf8f1;color:#482d20}.content{padding:2rem clamp(1rem,3vw,3rem)}header{display:flex;justify-content:space-between;gap:1rem;align-items:start}small{letter-spacing:.15em;color:#a76740;font-weight:800}h1{margin:.2rem 0;font:700 clamp(1.8rem,3vw,2.5rem) Georgia,serif}header p{color:#806b5a;max-width:650px}button{background:#74462e;color:#fff;border:0;border-radius:.6rem;padding:.7rem 1rem;font-weight:700}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:.8rem;margin:1.5rem 0}.summary article,.toolbar,.card,.empty{background:#fffdf9;border:1px solid #ead7c2;border-radius:1rem;padding:1rem}.summary b{display:block;font-size:1.5rem}.toolbar{display:flex;gap:.7rem;align-items:center}.toolbar>input{flex:1}.toolbar input,.toolbar select,.form input,.form select,.form textarea{padding:.65rem;border:1px solid #dec7aa;border-radius:.55rem;background:#fff}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(275px,1fr));gap:1rem;margin-top:1rem}.top{display:flex;justify-content:space-between;gap:.5rem}.card h2{margin:0;font-size:1.05rem}.top p{margin:.3rem 0;color:#806b5a}.top b{height:max-content;padding:.25rem .5rem;background:#e7f1e6;color:#397344;border-radius:99px;font-size:.72rem}dl{font-size:.82rem}dl div{display:grid;grid-template-columns:75px 1fr;margin-top:.45rem}dt{color:#8d7560}dd{margin:0;overflow-wrap:anywhere}.actions{display:flex;flex-wrap:wrap;gap:.5rem;margin-top:1rem}.actions a{border:1px solid #d7b99b;color:#70452c;padding:.55rem;border-radius:.55rem;text-decoration:none;font-size:.78rem}.actions button{font-size:.78rem}.empty{text-align:center;margin-top:1rem}.error,.success{padding:.8rem;border-radius:.6rem}.error{background:#fde8e4;color:#994c3d}.success{background:#e7f2e5;color:#376e3c}.overlay{position:fixed;inset:0;background:#0008;z-index:50;overflow:auto;padding:1rem}.modal{max-width:720px;margin:3rem auto;background:#fffdf9;padding:1.25rem;border-radius:1rem}.form{display:grid;grid-template-columns:repeat(2,1fr);gap:.8rem;margin:1rem 0}.form label{font-size:.8rem;font-weight:700}.form input,.form select,.form textarea{display:block;width:100%;box-sizing:border-box;margin-top:.3rem}.wide{grid-column:1/-1}.form textarea{min-height:80px}.modal footer{display:flex;justify-content:flex-end;gap:.7rem}@media(max-width:650px){header,.toolbar{flex-direction:column}.summary,.form{grid-template-columns:1fr}.toolbar{align-items:stretch}}
</style>
